const cursos = [
  { nome: "HTML do zero", preco: 0, vagas: 12, imagem: "html.png" },
  { nome: "JavaScript Essencial", preco: 149.9, vagas: 3, imagem: "js.png" },
  { nome: "Python para Dados", preco: 199.9, vagas: 0, imagem: "python.png" },
  { nome: "Git e GitHub", preco: 59.9, vagas: 20, imagem: "git.png" },
];

const vitrine = document.getElementById("vitrine");

// 1. Cria um card para cada curso
cursos.forEach((curso) => {
  const card = document.createElement("li");
  card.classList.add("card");

  const foto = document.createElement("img");
  foto.setAttribute("src", curso.imagem);
  foto.setAttribute("alt", `Capa do curso ${curso.nome}`);
  foto.setAttribute("width", "80");

  const titulo = document.createElement("h3");
  titulo.textContent = curso.nome;

  const preco = document.createElement("p");
  if (curso.preco === 0) {
    preco.textContent = "Grátis";
    preco.classList.add("gratis");
  } else {
    preco.textContent = `R$ ${curso.preco.toFixed(2).replace(".", ",")}`;
  }

  const vagas = document.createElement("p");
  if (curso.vagas === 0) {
    vagas.textContent = "Esgotado";
    card.classList.add("esgotado");
  } else if (curso.vagas <= 5) {
    vagas.textContent = `Últimas ${curso.vagas} vagas!`;
    vagas.style.color = "darkorange";
  } else {
    vagas.textContent = `${curso.vagas} vagas`;
  }

  card.appendChild(foto);
  card.appendChild(titulo);
  card.appendChild(preco);
  card.appendChild(vagas);
  vitrine.appendChild(card);
});

// 2. Destaca o primeiro curso disponível
const disponiveis = document.querySelectorAll(".card:not(.esgotado)");
disponiveis[0].classList.add("destaque");

const selo = document.createElement("strong");
selo.textContent = "Mais procurado";
disponiveis[0].insertAdjacentElement("afterbegin", selo);

// 3. Atualiza o resumo
const total = document.querySelectorAll(".card").length;
const gratis = document.querySelectorAll(".gratis").length;
document.getElementById("resumo").textContent =
  `${total} cursos, ${disponiveis.length} com vagas, ${gratis} grátis.`;

