const alunos = [
  { nome: "Ana", nota: 9 },
  { nome: "Bruno", nota: 5.5 },
  { nome: "Carla", nota: 7 },
];
const corpo = document.getElementById("corpo");
let soma = 0;

alunos.forEach((aluno) => {
  const linha = document.createElement("tr");

  const celulaNome = document.createElement("td");
  celulaNome.textContent = aluno.nome;

  const celulaNota = document.createElement("td");
  celulaNota.textContent = aluno.nota;

  const celulaSituacao = document.createElement("td");
  if (aluno.nota >= 7) {
    celulaSituacao.textContent = "Aprovado";
  } else {
    celulaSituacao.textContent = "Recuperação";
    linha.classList.add("alerta");
  }

  linha.appendChild(celulaNome);
  linha.appendChild(celulaNota);
  linha.appendChild(celulaSituacao);
  corpo.appendChild(linha);
  soma += aluno.nota;
});

const media = soma / alunos.length;
document.getElementById("media").textContent = `Média da turma: ${media.toFixed(1)}`;

